198: function syncWorldFromState() {
199:   const s = game.s
200:   for (const [name, info] of Object.entries(PART_INFO)) {
201:     const installed = !!s.parts[name]
202:     world.truck.setPart(name, installed)
203:     if (installed) {
204:       if (name === 'wheels') world.truck.setPart('wheels', true)
205:       world.truck.makeBolts(name, s.bolts[name] || [])
206:     }
207:     const p = world.pickups[name]
208:     if (p) {
209:       const gone = installed || (s.inventory[name] || 0) > 0
210:       p.taken = gone
211:       p.group.visible = !gone
212:     }
213:   }
214:   world.truck.group.position.set(s.truck.x, 0, s.truck.z)
215:   world.truck.group.rotation.y = s.truck.heading || 0
216:   world.truck.setCargo(!!s.cargo)
217:   if (s.engineRunning) {
218:     syncEngineSound()
219:   }
220:   syncMarkers()
221: }
