227: function syncEngineSound() {
228:   if (game.s.engineRunning) {
229:     sound.startEngine()
230:     sound.revEngine(game.idleRpm(), Math.min(1, game.tuneError().total + game.looseBolts() * 0.05))
231:   } else sound.stopEngine()
232: }
