248: function loop() {
249:   const dt = Math.min(0.05, clock.getDelta())
250:   const t = performance.now() / 1000
251: 
252:   if (mode === 'title') updateTitle(dt, t)
253:   else if (mode === 'dead') { /* keep rendering the dark room */ }
254:   else if (paused || (ui.panel && ui.panel !== 'torque')) {
255:     updateWorldAmbient(dt, t)
256:     ui.tickTorque(dt)
257:     updateHUD()
258:   } else {
259:     if (mode === 'walk') updateWalk(dt, t)
260:     if (mode === 'drive') updateDrive(dt, t)
261:     updateWorldAmbient(dt, t)
262:     ui.tickTorque(dt)
263:     game.tick(dt)
264:     if (game.dead) { mode = 'dead'; paused = true }
265:     updateHUD()
266:     saveAccum += dt
267:     if (saveAccum > 8) { saveAccum = 0; game.save() }
268:     if (ui.panel === 'tune') ui.updateTuneLive()
269:   }
270:   renderer.render(scene, camera)
271:   input.endFrame()
272: }
273: 
274: function updateWorldAmbient(dt, t) {
275:   world.update(dt, t)
276:   if (game.s.engineRunning) {
277:     sound.revEngine(game.idleRpm() + (mode === 'drive' && vehicle === 'truck' ? Math.abs(speed) * 85 : 0), Math.min(1, game.tuneError().total + game.looseBolts() * 0.08))
278:     if (Math.random() < dt * 14) world.puffExhaust()
279:   } else if (vehicle === 'truck' && mode === 'drive') {
280:     sound.revEngine(0, 1)
281:   }
282:   if (Math.random() < dt * 0.06 && !ui.panel) {
283:     // occasional creak / settling
284:     if (Math.random() > 0.5) sound.burst({ freq: 500 + Math.random() * 600, q: 3, dur: 0.18, gain: 0.012, rate: 0.4 })
285:   }
286: }
287: 
288: function updateTitle(dt, t) {
289:   titleTime += dt
290:   camera.fov = 56
291:   camera.updateProjectionMatrix()
292:   camera.position.set(4.55 + Math.sin(t * 0.08) * 0.18, 2.02 + Math.sin(t * 0.11) * 0.04, 4.7 + Math.cos(t * 0.06) * 0.12)
293:   camera.lookAt(0.15, 1.18, -0.55)
294:   world.update(dt, t)
295:   if (game.s.engineRunning) {} // keep title quiet
296: }
297: 
298: function updateWalk(dt, t) {
299:   camera.fov += (64 - camera.fov) * 0.1
300:   camera.updateProjectionMatrix()
301:   const look = input.consumeLook()
302:   if (!ui.panel) {
303:     player.yaw -= look.x * 0.0022
304:     player.pitch -= look.y * 0.0022
305:     player.pitch = Math.max(-1.35, Math.min(1.35, player.pitch))
306:   }
307:   const axis = ui.panel ? { x: 0, y: 0 } : input.axis()
308:   const fatigue = game.s.meters.fatigue
309:   const sprint = input.sprint() && fatigue < 80 && game.s.meters.stamina !== 0
310:   const speedWalk = (sprint ? 4.2 : 2.7) * (1 - Math.min(0.35, fatigue / 280)) * (game.s.health < 35 ? 0.72 : 1)
311:   const forward = tmpV.set(-Math.sin(player.yaw), 0, -Math.cos(player.yaw))
312:   const right = tmpV2.set(Math.cos(player.yaw), 0, -Math.sin(player.yaw))
313:   const wish = new THREE.Vector3()
314:   wish.addScaledVector(forward, -axis.y).addScaledVector(right, axis.x)
315:   if (wish.lengthSq() > 0) wish.normalize().multiplyScalar(speedWalk * dt)
316:   const moved = tryMove(wish.x, wish.z)
317:   const movedLen = Math.hypot(moved.x, moved.z)
318:   player.stepDist += movedLen
319:   if (movedLen > 0.0005) {
320:     player.bob += dt * (sprint ? 10 : 7.2)
321:     if (player.stepDist > 1.6) { player.stepDist = 0; sound.step(sprint ? 1.4 : 1) }
322:   } else {
323:     player.bob *= 0.9
324:   }
325:   const bobY = Math.sin(player.bob) * (sprint ? 0.045 : 0.028)
326:   const bobX = Math.cos(player.bob * 0.5) * 0.018
327:   camera.position.set(player.pos.x + right.x * bobX, player.pos.y + bobY, player.pos.z + right.z * bobX)
328:   camera.rotation.set(player.pitch, player.yaw, Math.sin(player.bob * 0.5) * 0.004)
329: 
330:   updateInteractions(dt)
331:   updateMountHints()
332:   updateVehicleProximity()
333: }
334: 
335: function tryMove(dx, dz) {
336:   const r = 0.26
337:   let mx = 0, mz = 0
338:   if (!blockedAt(player.pos.x + dx, player.pos.z, r)) { player.pos.x += dx; mx = dx }
339:   if (!blockedAt(player.pos.x, player.pos.z + dz, r)) { player.pos.z += dz; mz = dz }
340:   // keep inside the valley
341:   player.pos.x = Math.max(-170, Math.min(170, player.pos.x))
342:   player.pos.z = Math.max(-170, Math.min(170, player.pos.z))
343:   return { x: mx, z: mz }
344: }
345: 
346: function blockedAt(x, z, r) {
347:   for (const c of world.colliders) {
348:     if (x > c.minX - r && x < c.maxX + r && z > c.minZ - r && z < c.maxZ + r) return true
349:   }
350:   for (const tc of world.treeColliders) {
351:     if ((x - tc.x) ** 2 + (z - tc.z) ** 2 < (tc.r + r) ** 2) return true
352:   }
353:   return false
354: }
355: 
356: // ---------------------------------------------------------------- interactions
357: function updateInteractions(dt) {
358:   current = null
359:   if (ui.panel) { ui.setPrompt(''); return }
360:   raycaster.setFromCamera(screenCenter, camera)
361:   const hits = raycaster.intersectObjects(world.interactables, false)
362:   for (const hit of hits) {
363:     if (hit.distance > 3.4) continue
364:     const def = hit.object.userData.interact
365:     if (!def) continue
366:     const resolved = resolveInteraction(def)
367:     if (resolved) { current = resolved; break }
368:   }
369:   jobPrompt = jobInteraction()
370:   if (jobPrompt) {
371:     const held = input.keys.has('KeyE') || ui.actionHeld
372:     if (jobPrompt.enabled) {
373:       if (held) {
374:         holdProgress += dt
375:         if (holdProgress >= jobPrompt.hold) {
376:           holdProgress = 0
377:           completeJobAction(jobPrompt)
378:         }
379:       } else holdProgress = 0
380:     } else holdProgress = 0
381:     ui.setPrompt(jobPrompt.text, { blocked: !jobPrompt.enabled, hold: jobPrompt.enabled ? jobPrompt.hold : 0, progress: holdProgress / jobPrompt.hold, key: 'E' })
382:     return
383:   }
384:   holdProgress = 0
385:   if (current) {
386:     ui.setPrompt(current.blocked ? current.reason : current.text, { blocked: current.blocked })
387:   } else {
388:     ui.setPrompt('')
389:   }
390: }
391: 
392: function updateMountHints() {
393:   if (!world.mountHints) return
394:   for (const [name, sprite] of Object.entries(world.mountHints)) {
395:     sprite.visible = !game.s.parts[name] && (game.s.inventory[name] || 0) > 0
396:     if (sprite.visible) sprite.material.opacity = 0.55 + Math.sin(performance.now() * 0.004) * 0.25
397:   }
398: }
399: 
400: function updateVehicleProximity() {
401:   // no-op placeholder; interactions handle entry
402: }
403: 
404: function resolveInteraction(def) {
405:   const id = def.id
406:   const s = game.s
407:   if (id.startsWith('pickup_')) {
408:     const part = id.slice(7)
409:     if (world.pickups[part]?.taken) return null
410:     return { text: `Pick up ${PART_INFO[part]?.name || def.label}`, action: 'pickup', part, key: 'E' }
411:   }
412:   if (id.startsWith('mount_')) {
413:     const part = id.slice(6)
414:     const info = PART_INFO[part]
415:     if (!info) return null
416:     const inv = s.inventory[part] || 0
417:     if (!s.parts[part]) {
418:       if (!inv) return { text: `Install ${info.name}`, blocked: true, reason: `${info.name} is still in the garage.`, action: 'install', part }
419:       if (tool !== info.tool) return { text: `Install ${info.name}`, blocked: true, reason: `Requires a ${info.tool}mm socket.`, action: 'install', part }
420:       return { text: `Install ${info.name} · ${info.tool}mm`, action: 'install', part }
421:     }
422:     const next = game.nextBolt(part)
423:     if (next < 0) return { text: `${info.name} · at spec`, action: null }
424:     const state = s.bolts[part][next]
425:     const strip = state === 'stripped'
426:     if (tool !== info.tool) return { text: strip ? 'Replace stripped bolt' : `Re-torque ${info.name}`, blocked: true, reason: `Requires a ${info.tool}mm socket.`, action: 'retorque', part, index: next }
427:     if (strip && (s.inventory.boltKit || 0) <= 0) return { text: 'Replace stripped bolt', blocked: true, reason: 'No bolt kit. The parts terminal sells them.', action: 'retorque', part, index: next }
428:     return { text: strip ? 'Replace stripped bolt' : `Torque ${info.name} · bolt ${next + 1}/${info.bolts}`, action: 'retorque', part, index: next }
429:   }
430:   switch (id) {
431:     case 'manual': return { text: 'Read the service log', action: 'manual' }
432:     case 'board': return { text: 'Check the job board', action: 'board' }
433:     case 'store': return { text: 'Use the parts terminal', action: 'store' }
434:     case 'radio': return { text: 'Turn the radio on', action: 'radio' }
435:     case 'cot': return { text: 'Sleep until morning', action: 'sleep' }
436:     case 'sink': return { text: 'Wash up / drink from the tap', action: 'sink' }
437:     case 'food': return { text: 'Eat cold beans', action: 'eat' }
438:     case 'coffee': return { text: 'Pour coffee', action: 'coffee' }
439:     case 'cigarettes': return { text: 'Smoke one', action: 'smoke' }
440:     case 'tune': return { text: 'Tune the engine', action: 'tune' }
441:     case 'ignition':
442:     case 'truck_drive':
443:       if (s.engineRunning) return { text: 'Get into The Patient', action: 'enter_truck' }
444:       return { text: 'Crank the engine', action: 'crank' }
445:     case 'moped_drive': return { text: 'Ride the moped', action: 'enter_moped' }
446:     case 'fuel_tank': {
447:       if ((s.inventory.fuel || 0) <= 0) return { text: 'Fill the fuel tank', blocked: true, reason: 'No fuel can. Buy one at the parts terminal.', action: 'fuel' }
448:       return { text: 'Fill the fuel tank · 1 can', action: 'fuel' }
449:     }
450:     case 'oil_fill': {
451:       if ((s.inventory.oil || 0) <= 0) return { text: 'Fill engine oil', blocked: true, reason: 'No oil. Buy a jug at the parts terminal.', action: 'oil' }
452:       return { text: 'Fill engine oil · 1 jug', action: 'oil' }
453:     }
454:     case 'coolant_fill': {
455:       if ((s.inventory.coolant || 0) <= 0) return { text: 'Fill coolant', blocked: true, reason: 'No antifreeze. Buy a jug at the parts terminal.', action: 'coolant' }
456:       return { text: 'Fill coolant · 1 jug', action: 'coolant' }
457:     }
458:   }
459:   return null
460: }
461: 
462: function doAction() {
463:   if (mode === 'title' || game.dead) return
464:   if (ui.panel) {
465:     return
466:   }
467:   if (mode === 'drive') {
468:     if (jobInteraction()?.enabled) return // hold handled in loop
469:     exitVehicle()
470:     return
471:   }
472:   if (jobPrompt) return
473:   if (!current) return
474:   if (current.blocked) {
475:     sound.error()
476:     ui.toast(current.reason || 'Not now.', 'bad')
477:     game.s.meters.stress = Math.min(100, game.s.meters.stress + 1)
478:     return
479:   }
480:   switch (current.action) {
481:     case 'pickup': pickupPart(current.part); break
482:     case 'install': installPart(current.part); break
483:     case 'retorque': retorque(current.part, current.index); break
484:     case 'manual': ui.openPanel('manual'); break
485:     case 'board': ui.openPanel('board'); break
486:     case 'store': ui.openPanel('store'); break
487:     case 'tune': ui.openPanel('tune'); break
488:     case 'radio': {
489:       const on = sound.toggleRadio()
490:       ui.toast(on ? 'The radio crackles to life. Something slow and sad.' : 'Radio off.')
491:       break
492:     }
493:     case 'sleep': {
494:       const msg = game.sleep()
495:       ui.toast(msg, 'good')
496:       sound.clunk()
497:       break
498:     }
499:     case 'sink': ui.toast(game.drink(), 'good'); break
500:     case 'eat': ui.toast(game.eat(), ''); break
501:     case 'coffee': ui.toast(game.coffee(), ''); break
502:     case 'smoke': ui.toast(game.smoke(), ''); break
503:     case 'crank': {
504:       const res = game.startEngine()
505:       ui.toast(res.msg, res.running ? 'good' : 'bad')
506:       if (res.running) {
507:         syncEngineSound()
508:         game.s.meters.stress = Math.max(0, game.s.meters.stress - 6)
509:       } else {
