298: function updateWalk(dt, t) {
299:   camera.fov += (64 - camera.fov) * 0.1
300:   camera.updateProjectionMatrix()
301:   const look = input.consumeLook()
302:   if (!ui.panel) {
303:     player.yaw -= look.x * 0.0022
304:     player.pitch -= look.y * 0.0022
305:     player.pitch = Math.max(-1.35, Math.min(1.35, player.pitch))
306:   }
307:   const axis = ui.panel ? { x: 0, y: 0 } : input.axis()
308:   const fatigue = game.s.meters.fatigue
309:   const sprint = input.sprint() && fatigue < 80 && game.s.meters.stamina !== 0
310:   const speedWalk = (sprint ? 4.2 : 2.7) * (1 - Math.min(0.35, fatigue / 280)) * (game.s.health < 35 ? 0.72 : 1)
311:   const forward = tmpV.set(-Math.sin(player.yaw), 0, -Math.cos(player.yaw))
312:   const right = tmpV2.set(Math.cos(player.yaw), 0, -Math.sin(player.yaw))
313:   const wish = new THREE.Vector3()
314:   wish.addScaledVector(forward, -axis.y).addScaledVector(right, axis.x)
315:   if (wish.lengthSq() > 0) wish.normalize().multiplyScalar(speedWalk * dt)
316:   const moved = tryMove(wish.x, wish.z)
317:   const movedLen = Math.hypot(moved.x, moved.z)
318:   player.stepDist += movedLen
319:   if (movedLen > 0.0005) {
320:     player.bob += dt * (sprint ? 10 : 7.2)
321:     if (player.stepDist > 1.6) { player.stepDist = 0; sound.step(sprint ? 1.4 : 1) }
322:   } else {
323:     player.bob *= 0.9
324:   }
325:   const bobY = Math.sin(player.bob) * (sprint ? 0.045 : 0.028)
326:   const bobX = Math.cos(player.bob * 0.5) * 0.018
327:   camera.position.set(player.pos.x + right.x * bobX, player.pos.y + bobY, player.pos.z + right.z * bobX)
328:   camera.rotation.set(player.pitch, player.yaw, Math.sin(player.bob * 0.5) * 0.004)
329: 
330:   updateInteractions(dt)
331:   updateMountHints()
332:   updateVehicleProximity()
333: }
334: 
335: function tryMove(dx, dz) {
336:   const r = 0.26
337:   let mx = 0, mz = 0
338:   if (!blockedAt(player.pos.x + dx, player.pos.z, r)) { player.pos.x += dx; mx = dx }
339:   if (!blockedAt(player.pos.x, player.pos.z + dz, r)) { player.pos.z += dz; mz = dz }
340:   // keep inside the valley
341:   player.pos.x = Math.max(-170, Math.min(170, player.pos.x))
342:   player.pos.z = Math.max(-170, Math.min(170, player.pos.z))
343:   return { x: mx, z: mz }
344: }
