346: function blockedAt(x, z, r) {
347:   for (const c of world.colliders) {
348:     if (x > c.minX - r && x < c.maxX + r && z > c.minZ - r && z < c.maxZ + r) return true
349:   }
350:   for (const tc of world.treeColliders) {
351:     if ((x - tc.x) ** 2 + (z - tc.z) ** 2 < (tc.r + r) ** 2) return true
352:   }
353:   return false
354: }
