356: // ---------------------------------------------------------------- interactions
357: function updateInteractions(dt) {
358:   current = null
359:   if (ui.panel) { ui.setPrompt(''); return }
360:   raycaster.setFromCamera(screenCenter, camera)
361:   const hits = raycaster.intersectObjects(world.interactables, false)
362:   for (const hit of hits) {
363:     if (hit.distance > 3.4) continue
364:     const def = hit.object.userData.interact
365:     if (!def) continue
366:     const resolved = resolveInteraction(def)
367:     if (resolved) { current = resolved; break }
368:   }
369:   jobPrompt = jobInteraction()
370:   if (jobPrompt) {
371:     const held = input.keys.has('KeyE') || ui.actionHeld
372:     if (jobPrompt.enabled) {
373:       if (held) {
374:         holdProgress += dt
375:         if (holdProgress >= jobPrompt.hold) {
376:           holdProgress = 0
377:           completeJobAction(jobPrompt)
378:         }
379:       } else holdProgress = 0
380:     } else holdProgress = 0
381:     ui.setPrompt(jobPrompt.text, { blocked: !jobPrompt.enabled, hold: jobPrompt.enabled ? jobPrompt.hold : 0, progress: holdProgress / jobPrompt.hold, key: 'E' })
382:     return
383:   }
384:   holdProgress = 0
385:   if (current) {
386:     ui.setPrompt(current.blocked ? current.reason : current.text, { blocked: current.blocked })
387:   } else {
388:     ui.setPrompt('')
389:   }
390: }
