550: function retorque(part, index) {
551:   const state = game.s.bolts[part]?.[index]
552:   if (state === 'stripped') {
553:     if ((game.s.inventory.boltKit || 0) <= 0) { ui.toast('No bolt kit to replace the stripped stud.', 'bad'); return }
554:     game.s.inventory.boltKit--
