563: function startTorque(part, index) {
564:   const info = PART_INFO[part]
565:   if (!game.s.parts[part]) return
566:   if (!game.s.bolts[part]) game.s.bolts[part] = new Array(info.bolts).fill(null)
567:   if (index < 0) return
568:   if (tool !== info.tool) {
569:     sound.error()
570:     ui.toast(`Need a ${info.tool}mm socket.`, 'bad')
571:     return
572:   }
573:   const [lo, hi] = info.torque
574:   ui.showTorque({ part, label: info.name, lo, hi, index, total: info.bolts })
575:   if (ui.torque) ui.torque.startedAt = performance.now()
