596: function jobInteraction() {
597:   const j = game.s.job
598:   if (!j) return null
599:   const target = game.jobTarget()
600:   if (!target) return null
601:   const pos = mode === 'drive' ? world.truck.group.position : player.pos
602:   if (mode === 'drive' && vehicle === 'moped') {
603:     // moped position instead
604:   }
605:   const p = mode === 'drive' ? (vehicle === 'truck' ? world.truck.group.position : world.truck.group.position) : player.pos
606:   const px = mode === 'drive' ? (vehicle === 'truck' ? world.truck.group.position.x : world.moped.group.position.x) : player.pos.x
607:   const pz = mode === 'drive' ? (vehicle === 'truck' ? world.truck.group.position.z : world.moped.group.position.z) : player.pos.z
608:   const dist = Math.hypot(px - target.x, pz - target.z)
609:   if (dist > 9) return null
610:   if (mode !== 'drive') return { text: `Get a vehicle for ${target.label}`, enabled: false, hold: 0, act: 'none' }
611:   if (Math.abs(speed) > 1.4) return { text: 'Stop the vehicle to load', enabled: false, hold: 0, act: 'none' }
612:   if (j.id === 'firewood' && vehicle !== 'truck') return { text: 'Firewood needs the truck', enabled: false, hold: 0, act: 'none' }
613:   if (j.stage === 'to_farm') {
614:     return { text: j.id === 'courier' ? 'Drop the crate at Miller farm — hold E' : 'Load firewood at Miller farm — hold E', enabled: true, hold: j.id === 'courier' ? 2.6 : 4.2, act: 'load' }
615:   }
616:   return { text: 'Unload firewood at the store — hold E', enabled: true, hold: 4.2, act: 'unload' }
617: }
