676:     game.s.truck = { x: world.truck.group.position.x, z: world.truck.group.position.z, heading }
677:     t.x = game.s.truck.x; t.z = game.s.truck.z; t.heading = heading
678:     const side = new THREE.Vector3(Math.cos(heading), 0, -Math.sin(heading))
679:     player.pos.set(world.truck.group.position.x - side.x * 1.5, 1.62, world.truck.group.position.z - side.z * 1.5)
680:     game.save()
681:   } else {
682:     player.pos.set(world.moped.group.position.x - 1.0, 1.62, world.moped.group.position.z)
683:     sound.stopMoped()
684:   }
685:   // don't place the player inside a wall
686:   if (blockedAt(player.pos.x, player.pos.z, 0.26)) {
687:     player.pos.set(world.truck.group.position.x + 2.2, 1.62, world.truck.group.position.z + 2.5)
688:   }
689:   mode = 'walk'
690:   vehicle = null
691:   speed = 0
692:   document.body.classList.remove('driving')
693:   ui.setPrompt('')
694:   ui.toast('On foot. The dirt is cold.', '')
